def max_sum_increasing_subseq(arr, n, i, k):
    target = arr[k]
    dp = []
    best = 0
    for j in range(i + 1):
        if arr[j] >= target:
            dp.append(0)
            continue
        best_prev = 0
        for t in range(j):
            if arr[t] < arr[j] and dp[t] > best_prev:
                best_prev = dp[t]
        dp.append(arr[j] + best_prev)
        if dp[j] > best:
            best = dp[j]
    return best + target
