    n = len(arr)
    prefix = [0] * (n + 1)
    for i, x in enumerate(arr):
        prefix[i + 1] = prefix[i] + x
    total = 0
    for i in range(n):
        for j in range(i, n):
            if (j - i + 1) % 2 == 1:
                total += prefix[j + 1] - prefix[i]
    return total
